// spec: specs/customers-pricing.md §10 · кейсы .qa/tests/customers/cust-11, cust-12, cust-13 · несколько ролей (admin + rep) — пишется вручную (asUser)
// #5a2dbd (עבר QA 29.10): клиент, которому ссылка не создавалась (или все ссылки отменены), — «ללא כניסה לקטלוג»:
//   в списке, в карточке (нейтральная плашка «הלקוח נרשם ללא כניסה לקטלוג…», без «שלחו ללקוח את קישור ההצטרפות…»),
//   в фильтре admin; «יצירת קישור» и «⋮ ← קישור הצטרפות» остаются. Ссылка создана, не зарегистрирован — «ממתין להזמנה».
//   У נציג статусы только «פעיל» / «מושבת» («test» — «פעיל»).
// Конечные статусы admin читаются ПОСЛЕ ответа GET customer_invites (до ответа — скелет, #08cb68; см. customer-status-loading.spec.ts).
// Данные: QA-AUTO-cust-5a2dbd-<ts>-*; без заказов; ссылки не копируются/не отправляются; afterAll — admin удаляет клиентов.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import {
  rowOf, openList, openListReady, openCardReady, cardTag, search, openNewCustomer, rest, deleteCustomersByPrefix, customerId,
  BTN_SAVE, BTN_LINK, SWITCH_LINK, ST_NO_CATALOG, ST_PENDING, ST_ACTIVE, ST_INVITED, BANNER_NO_CATALOG, BANNER_SEND_LINK, TEST_PHONE,
} from './_customers';

test.describe.configure({ mode: 'serial' });

const PREFIX = `QA-AUTO-cust-5a2dbd-${Date.now().toString().slice(-7)}`;
const NOLINK = `${PREFIX}-nolink`;
const LINK = `${PREFIX}-link`;
const REP_NOLINK = `${PREFIX}-rep`;

async function create(page: Page, name: string, withLink: boolean) {
  await openList(page);
  const dlg = await openNewCustomer(page);
  const sw = dlg.getByRole('switch', { name: SWITCH_LINK });
  if (!withLink) await sw.click();
  await expect(sw).toHaveAttribute('aria-checked', String(withLink));
  await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(name);
  const [resp] = await Promise.all([
    page.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
    dlg.getByRole('button', { name: withLink ? BTN_LINK : BTN_SAVE }).click(),
  ]);
  expect(resp.status(), `POST customers «${name}»`).toBe(201);
  if (withLink) {
    await expect(dlg.getByRole('heading', { name: 'החשבון נפתח' })).toBeVisible({ timeout: 15_000 });
    await dlg.getByRole('button', { name: 'סגירה' }).click(); // ссылку не копируем
  }
  await expect(page.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
  const body = await resp.json();
  return (Array.isArray(body) ? body[0] : body).id as string;
}

const isInvites = (method: string) => (r: { url(): string; request(): { method(): string } }) =>
  /\/rest\/v1\/customer_invites(\?|$)/.test(r.url()) && r.request().method() === method;

test.describe('customers — סטטוס «ללא כניסה לקטלוג» ללקוח בלי קישור (#5a2dbd)', () => {
  let nolinkId = '';

  test.afterAll(async ({ browser }) => {
    await deleteCustomersByPrefix(browser, test.info().project.use.baseURL, PREFIX);
  });

  test('מנהל: לקוח בלי קישור — ברשימה ובכרטיס «ללא כניסה לקטלוג», הודעה ניטרלית בלי «שלחו ללקוח…», «יצירת קישור» ו-⋮ «קישור הצטרפות» נשארים #5a2dbd @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin');
    nolinkId = await create(admin, NOLINK, false);

    await openListReady(admin);
    await search(admin, NOLINK);
    const row = rowOf(admin, NOLINK);
    await expect(row).toContainText(ST_NO_CATALOG, { timeout: 20_000 });
    await expect(row).not.toContainText(ST_PENDING);
    await row.getByRole('button', { name: 'פעולות' }).click();
    await expect(admin.getByRole('menuitem', { name: 'קישור הצטרפות' })).toBeVisible(); // не нажимаем
    await admin.keyboard.press('Escape');

    await openCardReady(admin, nolinkId, NOLINK);
    await expect(cardTag(admin, ST_NO_CATALOG)).toBeVisible();
    await expect(cardTag(admin, ST_PENDING)).toHaveCount(0);
    await expect(admin.getByText(BANNER_NO_CATALOG)).toBeVisible();
    await expect(admin.getByText(BANNER_SEND_LINK)).toHaveCount(0);
    await expect(admin.getByRole('button', { name: 'יצירת קישור' })).toBeVisible();
  });

  test('מנהל: לקוח עם קישור שלא נמסר — «ממתין להזמנה»; סינון «ללא כניסה לקטלוג» / «ממתין להזמנה» / «פעיל» מפריד ביניהם #5a2dbd @desktop @data', async ({ asUser }) => {
    test.skip(!nolinkId, 'клиент без ссылки не создан');
    const admin = await asUser('admin');
    await create(admin, LINK, true);

    await openListReady(admin);
    const status = admin.getByRole('combobox', { name: 'סטטוס' });
    await admin.getByRole('button', { name: 'סינון' }).click();
    await expect(status.getByRole('option')).toHaveText(['כל הסטטוסים', ST_ACTIVE, ST_INVITED, ST_PENDING, ST_NO_CATALOG, 'מושבת']);
    await search(admin, PREFIX);
    await expect(rowOf(admin, LINK)).toContainText(ST_PENDING, { timeout: 20_000 });
    await expect(rowOf(admin, NOLINK)).toContainText(ST_NO_CATALOG);

    await status.selectOption({ label: ST_NO_CATALOG });
    await expect(rowOf(admin, NOLINK)).toBeVisible();
    await expect(rowOf(admin, LINK)).toHaveCount(0);

    await status.selectOption({ label: ST_PENDING });
    await expect(rowOf(admin, LINK)).toBeVisible();
    await expect(rowOf(admin, NOLINK)).toHaveCount(0);

    await status.selectOption({ label: ST_ACTIVE });
    await expect(rowOf(admin, LINK)).toHaveCount(0);
    await expect(rowOf(admin, NOLINK)).toHaveCount(0);
    await search(admin, 'test');
    await expect(rowOf(admin, TEST_PHONE)).toBeVisible({ timeout: 20_000 });
  });

  test('מנהל: «יצירת קישור» בכרטיס → «ממתין להזמנה»; «ביטול הקישור» (כל הקישורים בוטלו) → שוב «ללא כניסה לקטלוג» #5a2dbd @desktop @data', async ({ asUser }) => {
    test.skip(!nolinkId, 'клиент без ссылки не создан');
    const admin = await asUser('admin');
    await openCardReady(admin, nolinkId, NOLINK);
    await expect(cardTag(admin, ST_NO_CATALOG)).toBeVisible();

    const [created] = await Promise.all([
      admin.waitForResponse(isInvites('POST')),
      admin.getByRole('button', { name: 'יצירת קישור' }).click(),
    ]);
    expect(created.status(), 'POST customer_invites').toBe(201);
    const dlg = admin.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הזמנת לקוח לקטלוג' })).toBeVisible();
    // ссылка создана, клиент не зарегистрирован → «ממתין להזמנה» (комментарий программиста)
    await expect(cardTag(admin, ST_PENDING)).toBeVisible({ timeout: 20_000 });

    const [deleted] = await Promise.all([
      admin.waitForResponse(isInvites('DELETE')),
      dlg.getByRole('button', { name: 'ביטול הקישור' }).click(),
    ]);
    expect(deleted.status(), 'DELETE customer_invites').toBe(204);
    await expect(cardTag(admin, ST_NO_CATALOG)).toBeVisible({ timeout: 20_000 });
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(admin.getByText(BANNER_NO_CATALOG)).toBeVisible();
    const left = await rest(admin, 'GET', `customer_invites?select=id&customer_id=eq.${nolinkId}`);
    expect(left.json, 'ссылок не осталось').toEqual([]);

    await openListReady(admin);
    await search(admin, NOLINK);
    await expect(rowOf(admin, NOLINK)).toContainText(ST_NO_CATALOG, { timeout: 20_000 });
  });

  test('נציג: רק «פעיל» / «מושבת» — «test» פעיל ברשימה ובכרטיס, בסינון שני סטטוסים, לקוח שיצר בלי קישור — «פעיל» (אצל מנהל «ללא כניסה לקטלוג») #5a2dbd @desktop @data', async ({ asUser }) => {
    const rep = await asUser('rep');
    await openList(rep);
    const testRow = rowOf(rep, TEST_PHONE);
    await expect(testRow).toContainText(ST_ACTIVE, { timeout: 20_000 });
    await expect(testRow).not.toContainText(ST_PENDING);
    await rep.getByRole('button', { name: 'סינון' }).click();
    await expect(rep.getByRole('combobox', { name: 'סטטוס' }).getByRole('option')).toHaveText(['כל הסטטוסים', ST_ACTIVE, 'מושבת']);

    await create(rep, REP_NOLINK, false);
    const row = rowOf(rep, REP_NOLINK);
    await expect(row).toContainText(ST_ACTIVE, { timeout: 20_000 });
    for (const s of [ST_PENDING, ST_NO_CATALOG]) await expect(row).not.toContainText(s);

    const repCustId = await customerId(rep, REP_NOLINK);
    await rep.goto(`/customers/${repCustId}`);
    await expect(rep.getByRole('heading', { level: 1, name: REP_NOLINK })).toBeVisible({ timeout: 30_000 });
    await expect(cardTag(rep, ST_ACTIVE)).toBeVisible();
    for (const s of [ST_PENDING, ST_NO_CATALOG]) await expect(cardTag(rep, s)).toHaveCount(0);

    const testId = await customerId(rep, 'test');
    await rep.goto(`/customers/${testId}`);
    await expect(rep.getByRole('heading', { level: 1, name: 'test' })).toBeVisible({ timeout: 30_000 });
    await expect(cardTag(rep, ST_ACTIVE)).toBeVisible();
    await expect(cardTag(rep, ST_PENDING)).toHaveCount(0);

    // тот же клиент у admin — «ללא כניסה לקטלוג» (ссылка не создавалась)
    const admin = await asUser('admin');
    await openCardReady(admin, repCustId, REP_NOLINK);
    await expect(cardTag(admin, ST_NO_CATALOG)).toBeVisible();
  });
});
